class Solution:

	def minimizeSum(self, n, triangle):
		dp = [[-1 for j in range(n)] for i in range(n)]
		return self.cost(0, 0, n, triangle, dp)

	def cost(self, i, j, n, triangle, dp):
		if dp[i][j] != -1:
			return dp[i][j]
		if i == n - 1:
			return triangle[i][j]
		down = triangle[i][j] + self.cost(i + 1, j, n, triangle, dp)
		right = triangle[i][j] + self.cost(i + 1, j + 1, n, triangle, dp)
		dp[i][j] = min(down, right)
		return dp[i][j]
